Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAX_N = (1 << 19) + 5;
int N, K, MOD, MAX_VAL, BIT_COUNT[MAX_N], F[MAX_N];
int TMP1[20][MAX_N], TMP2[20][MAX_N], TMP3[20][MAX_N];
long long MOD_SQ;
long long WORK[20][MAX_N];
long long FACT[200005], INV_FACT[200005];

long long mod_pow(long long b, long long e) {
    long long r = 1;
    b %= MOD;
    while (e) {
        if (e & 1) r = (r * b) % MOD;
        b = (b * b) % MOD;
        e >>= 1;
    }
    return r;
}

void init_fac() {
    FACT[0] = 1;
    for (int i = 1; i <= MAX_VAL; ++i)
        FACT[i] = FACT[i-1] * i % MOD;
    INV_FACT[MAX_VAL] = mod_pow(FACT[MAX_VAL], MOD - 2);
    for (int i = MAX_VAL - 1; i >= 0; --i)
        INV_FACT[i] = INV_FACT[i+1] * (i+1) % MOD;
}

int next_pow2(int x) {
    int p = 1;
    while (p < x) p <<= 1;
    return p;
}

void fwht(int *arr, int len, bool inv = false) {
    static long long buf[MAX_N];
    for (int i = 0; i < len; ++i) buf[i] = arr[i];

    if (inv) {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += step << 1) {
                for (int j = 0; j < step; ++j) {
                    buf[i + step + j] = (buf[i + step + j] - buf[i + j]) % MOD;
                }
            }
        }
    } else {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += step << 1) {
                for (int j = 0; j < step; ++j) {
                    buf[i + step + j] = (buf[i + step + j] + buf[i + j]) % MOD;
                }
            }
        }
    }

    for (int i = 0; i < len; ++i) {
        arr[i] = (int)(buf[i] % MOD);
        if (arr[i] < 0) arr[i] += MOD;
    }
}

inline void mod_reduce(long long &x) {
    if (x >= MOD_SQ) x -= MOD_SQ;
}

void multiply_ops() {
    for (int i = 0; i <= 19; ++i) {
        memset(TMP1[i], 0, sizeof(int[MAX_VAL + 1]));
        memset(WORK[i], 0, sizeof(long long[MAX_VAL + 1]));
    }

    for (int i = 0; i <= MAX_VAL; ++i)
        TMP1[BIT_COUNT[i]][i] = F[i];

    for (int i = 0; i <= 19; ++i)
        fwht(TMP1[i], MAX_VAL + 1);

    for (int i = 0; i <= 19; ++i)
        for (int j = 0; i + j <= 19; ++j)
            for (int idx = 0; idx <= MAX_VAL; ++idx)
                mod_reduce(WORK[i + j][idx] += 1LL * TMP1[i][idx] * TMP2[j][idx]);

    for (int i = 0; i <= 19; ++i)
        for (int idx = 0; idx <= MAX_VAL; ++idx)
            TMP3[i][idx] = (int)(WORK[i][idx] % MOD);

    for (int i = 0; i <= 19; ++i)
        fwht(TMP3[i], MAX_VAL + 1, true);

    for (int i = 0; i <= MAX_VAL; ++i)
        F[i] = TMP3[BIT_COUNT[i]][i];
}

void square_ops() {
    static int buf[20][MAX_N];
    for (int i = 0; i <= 19; ++i)
        memset(WORK[i], 0, sizeof(long long[MAX_VAL + 1]));

    for (int i = 0; i <= 19; ++i)
        for (int j = 0; i + j <= 19; ++j)
            for (int idx = 0; idx <= MAX_VAL; ++idx)
                mod_reduce(WORK[i + j][idx] += 1LL * TMP2[i][idx] * TMP2[j][idx]);

    for (int i = 0; i <= 19; ++i)
        for (int idx = 0; idx <= MAX_VAL; ++idx)
            buf[i][idx] = (int)(WORK[i][idx] % MOD);

    for (int i = 0; i <= 19; ++i)
        fwht(buf[i], MAX_VAL + 1, true);

    for (int i = 0; i <= 19; ++i)
        memset(TMP2[i], 0, sizeof(int[MAX_VAL + 1]));

    for (int idx = 0; idx <= MAX_VAL; ++idx)
        TMP2[BIT_COUNT[idx]][idx] = buf[BIT_COUNT[idx]][idx];

    for (int i = 0; i <= 19; ++i)
        fwht(TMP2[i], MAX_VAL + 1);
}

int main() {
    scanf("%d%d%d", &N, &K, &MOD);
    MOD_SQ = 1LL * MOD * MOD;

    if (N & 1) {
        printf("%lld", mod_pow(K, N));
        return 0;
    }

    F[0] = 1;
    MAX_VAL = next_pow2(N + 1) - 1;
    init_fac();

    for (int i = 0; i <= MAX_VAL; ++i)
        BIT_COUNT[i] = __builtin_popcount(i);

    for (int i = 0; i <= MAX_VAL; ++i)
        TMP2[BIT_COUNT[i]][i] = INV_FACT[i];

    for (int i = 0; i <= 19; ++i)
        fwht(TMP2[i], MAX_VAL + 1);

    int orig_k = K;
    while (K) {
        if (K & 1) multiply_ops();
        K >>= 1;
        if (K) square_ops();
    }

    long long res = (mod_pow(orig_k, N) - FACT[N] * F[N] % MOD + MOD) % MOD;
    printf("%lld", res);
    return 0;
}
